def search(nums, t):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == t:
            return mid
        if nums[mid] < t:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
print(search([1, 3, 5, 7], 4))
